# WARNING: Under review - generated by LLM.

"""Week 4, Day 2: authorize effects and record durable receipts.

The workspace bounds every tool to one explicit root, rejects protected and
secret paths, refuses symlink traversal, requires inspection before
overwrite, and atomically replaces files so a crash never leaves a torn
write.  Model-dispatched side effects are default-deny: an operator
``confirm_tool`` callback must approve writes, edits, and commands.

Every dispatched tool records an immutable ``EffectReceipt`` (Day 2 feature):
the validated action, normalized inputs, exit state, changed artifacts, and a
content-address.  Durable crash/effect recovery is taught by Day 6's
exactly-once reconcile; this file deliberately has no mutation journal or
undo machinery.
"""

import hashlib
import heapq
import os
import signal
import stat
import subprocess
import uuid
from collections.abc import Callable
from dataclasses import dataclass, field
from pathlib import Path
from threading import Event, Thread
from time import monotonic

from .protocol import AgentError, ToolAction
from .receipts import EffectReceipt, ReceiptStore


_PROTECTED_NAMES = frozenset(
    {
        ".env",
        ".aws",
        ".azure",
        ".docker",
        ".git",
        ".gnupg",
        ".kube",
        ".netrc",
        ".npmrc",
        ".pypirc",
        ".ssh",
        ".tiny-llm",
        "id_rsa",
        "id_ed25519",
    }
)


def _protected_path_reason(parts: tuple[str, ...]) -> str | None:
    """Describe why path components cross a protected metadata or secret path."""

    for part in parts:
        lower = part.lower()
        if lower == ".git":
            return ".git is not accessible"
        if (
            lower in _PROTECTED_NAMES
            or lower.startswith(".env.")
            or lower.startswith(".tiny-llm-agent-")
            or lower.startswith(".tiny-llm-undo-")
        ):
            return "potential secret files are not accessible"
        if lower.endswith((".pem", ".key")):
            return "potential key files are not accessible"
    return None


@dataclass(frozen=True)
class _PreparedWrite:
    """A validated write and the file state it is allowed to replace."""

    path: Path
    content: bytes
    expected_digest: bytes | None
    expected_mode: int | None
    after_mode: int
    parent_identity: tuple[int, int]


@dataclass(frozen=True)
class ToolPolicy:
    """Filesystem and command boundaries for one workspace."""

    root: Path
    allow_writes: bool = False
    allowed_commands: tuple[tuple[str, ...], ...] = ()
    max_file_bytes: int = 64 * 1024
    max_write_bytes: int = 64 * 1024
    max_list_entries: int = 200
    max_tool_output_chars: int = 16_000
    command_timeout_seconds: float = 30.0
    _root_identity: tuple[int, int] = field(init=False, repr=False, compare=False)

    def __post_init__(self) -> None:
        """Normalize the root and reject invalid limits."""

        root = self.root.resolve()
        object.__setattr__(self, "root", root)
        numeric_limits = (
            self.max_file_bytes,
            self.max_write_bytes,
            self.max_list_entries,
            self.max_tool_output_chars,
            self.command_timeout_seconds,
        )
        if any(limit <= 0 for limit in numeric_limits):
            raise ValueError("tool policy limits must be positive")
        if not root.exists() or not root.is_dir():
            raise ValueError("workspace root must be an existing directory")
        root_status = os.stat(root, follow_symlinks=False)
        if not stat.S_ISDIR(root_status.st_mode):
            raise ValueError("workspace root must be a directory")
        object.__setattr__(
            self,
            "_root_identity",
            (root_status.st_dev, root_status.st_ino),
        )
        home = Path.home().resolve()
        if root.parent == root or root == home or root in home.parents:
            raise ValueError("workspace root is too broad")
        if reason := _protected_path_reason(root.parts):
            raise ValueError(f"workspace root is protected: {reason}")
        for command in self.allowed_commands:
            if not command or any(
                not isinstance(part, str) or not part or "\x00" in part
                for part in command
            ):
                raise ValueError("allowed commands must contain non-empty arguments")


@dataclass
class Workspace:
    """Bounded tools over one explicit workspace root."""

    policy: ToolPolicy
    confirm_tool: Callable[[ToolAction], bool] | None = None
    observed_files: dict[Path, bytes] = field(default_factory=dict, init=False)
    modified_files: set[Path] = field(default_factory=set, init=False)
    uncertain_modified_files: set[Path] = field(default_factory=set, init=False)
    receipt_store: ReceiptStore | None = field(default=None, init=False)
    last_receipt: EffectReceipt | None = field(default=None, init=False)

    def bind_receipt_store(self, store: ReceiptStore) -> None:
        """Attach a durable receipt store; every effect after this is recorded."""

        if self.last_receipt is not None or store is None:
            raise ValueError("receipt store must be bound before any effect")
        self.receipt_store = store

    def _record_receipt(
        self,
        action: ToolAction,
        result: str,
        changed_artifacts: tuple[str, ...],
        *,
        tool_call_id: str | None = None,
    ) -> None:
        """Persist one immutable effect receipt for a dispatched tool."""

        exit_state = "uncertain"
        if result.startswith("error:"):
            exit_state = "error"
        elif not self.uncertain_modified_files:
            exit_state = "ok"
        receipt = EffectReceipt(
            tool_call_id=tool_call_id or f"{uuid.uuid4().hex}",
            tool=action.tool,
            arguments=action.arguments,
            exit_state=exit_state,
            result=result,
            changed_artifacts=changed_artifacts,
        )
        self.last_receipt = receipt
        if self.receipt_store is not None:
            self.receipt_store.put(receipt)

    @property
    def available_tools(self) -> frozenset[str]:
        """Expose only tools enabled by operator policy."""

        tools = {"list_files", "read_file"}
        if self.policy.allow_writes:
            tools.update({"write_file", "edit_file"})
        if self.policy.allowed_commands:
            tools.add("run_command")
        return frozenset(tools)

    def resolve_path(self, raw: str, *, must_exist: bool = True) -> Path:
        """Resolve one tool path inside the workspace, rejecting traversal."""

        if not isinstance(raw, str) or not raw or "\x00" in raw:
            raise AgentError("path must be a non-empty string")
        candidate = Path(raw)
        if not candidate.is_absolute():
            candidate = self.policy.root / candidate
        try:
            relative = candidate.resolve().relative_to(self.policy.root)
        except ValueError as error:
            raise AgentError("path escapes the workspace") from error
        self._reject_protected(relative)
        path = self.policy.root / relative
        if must_exist:
            # Reject symlinked components: a resolved path that differs from
            # the literal path means a link was followed.
            try:
                literal = candidate.relative_to(self.policy.root)
            except ValueError as error:
                raise AgentError("path escapes the workspace") from error
            for part in literal.parts:
                probe = self.policy.root.joinpath(
                    *literal.parts[: literal.parts.index(part) + 1]
                )
                if probe.is_symlink():
                    raise AgentError("symlinks are not accessible")
            if not path.exists():
                raise AgentError("path does not exist")
        return path

    def _reject_protected(self, relative: Path) -> None:
        if reason := _protected_path_reason(relative.parts):
            raise AgentError(reason)

    def list_files(self, raw: str = ".") -> str:
        """List one directory without following symlinks."""

        path = self.resolve_path(raw)
        if not path.is_dir():
            raise AgentError("list_files path must be a directory")
        lines: list[str] = []
        items = heapq.nsmallest(
            self.policy.max_list_entries,
            path.iterdir(),
            key=lambda entry: entry.name,
        )
        for item in items:
            if item.is_symlink():
                continue
            try:
                relative = item.relative_to(self.policy.root)
                self._reject_protected(relative)
            except AgentError:
                continue
            kind = "dir" if item.is_dir() else "file"
            lines.append(f"{kind} {relative}")
            if len(lines) == self.policy.max_list_entries:
                break
        return "\n".join(lines)

    def read_file(self, raw: str) -> str:
        """Read one bounded UTF-8 regular file."""

        path = self.resolve_path(raw)
        data = self._read_bounded_file(path, tool="read_file")
        content = data.decode("utf-8")
        self.observed_files[path] = self._digest(data)
        return content

    def write_file(self, raw: str, content: str) -> str:
        """Atomically create or replace an inspected file."""

        prepared = self._prepare_write(raw, content)
        return self._commit_write(prepared)

    def _prepare_write(self, raw: str, content: str) -> _PreparedWrite:
        """Validate a write completely before asking for operator approval."""

        if not self.policy.allow_writes:
            raise AgentError("writes are disabled; restart with --allow-writes")
        encoded = content.encode("utf-8")
        if len(encoded) > self.policy.max_write_bytes:
            raise AgentError(f"content exceeds {self.policy.max_write_bytes} bytes")
        path = self.resolve_path(raw, must_exist=False)
        relative = path.relative_to(self.policy.root)
        expected_digest = self.observed_files.get(path)
        parent, name = self._open_parent_directory(relative)
        try:
            parent_status = os.fstat(parent)
            current = self._read_regular_at(parent, name, tool="write_file")
        finally:
            os.close(parent)
        if current is None:
            if expected_digest is not None:
                raise AgentError("file changed since it was read; read it again")
            expected_mode = None
            after_mode = 0o600
        else:
            if expected_digest is None:
                raise AgentError(
                    "existing files must be read before they are overwritten"
                )
            current_content, current_status = current
            if self._digest(current_content) != expected_digest:
                raise AgentError("file changed since it was read; read it again")
            expected_mode = stat.S_IMODE(current_status.st_mode)
            after_mode = expected_mode & 0o777
        return _PreparedWrite(
            path,
            encoded,
            expected_digest,
            expected_mode,
            after_mode,
            (parent_status.st_dev, parent_status.st_ino),
        )

    def _commit_write(self, prepared: _PreparedWrite) -> str:
        """Revalidate and commit one previously prepared write."""

        relative = prepared.path.relative_to(self.policy.root)
        path = prepared.path
        self._revalidate_prepared_write(prepared)
        self.uncertain_modified_files.add(path)
        try:
            self._atomic_write(
                path,
                prepared.content,
                expected_digest=prepared.expected_digest,
                expected_mode=prepared.expected_mode,
                after_mode=prepared.after_mode,
                parent_identity=prepared.parent_identity,
            )
        except BaseException:
            self.uncertain_modified_files.discard(path)
            raise
        self.observed_files[path] = self._digest(prepared.content)
        self.modified_files.add(path)
        self.uncertain_modified_files.discard(path)
        return f"wrote {relative}"

    def edit_file(self, raw: str, old: str, new: str) -> str:
        """Make one exact, reviewable replacement in a read file."""

        prepared = self._prepare_edit(raw, old, new)
        return self._commit_write(prepared)

    def _prepare_edit(self, raw: str, old: str, new: str) -> _PreparedWrite:
        """Validate and compute an edit without changing the workspace."""

        if not self.policy.allow_writes:
            raise AgentError("writes are disabled; restart with --allow-writes")
        path = self.resolve_path(raw)
        if path not in self.observed_files:
            raise AgentError("files must be read before they are edited")
        if not old:
            raise AgentError("old text must not be empty")
        data = self._read_bounded_file(path, tool="edit_file")
        if self._digest(data) != self.observed_files[path]:
            raise AgentError("file changed since it was read; read it again")
        content = data.decode("utf-8")
        matches = content.count(old)
        if matches != 1:
            raise AgentError(f"old text must match exactly once; found {matches}")
        return self._prepare_write(raw, content.replace(old, new, 1))

    def run_command(self, argv: list[str]) -> str:
        """Run one exact allowlisted command with a bounded timeout."""

        command = self._prepare_command(argv)
        return self._run_command(command)

    def _prepare_command(self, argv: list[str]) -> tuple[str, ...]:
        if not self.policy.allowed_commands:
            raise AgentError("command execution is disabled")
        if (
            not isinstance(argv, list)
            or not argv
            or any(not isinstance(part, str) or not part for part in argv)
        ):
            raise AgentError("argv must be a non-empty array of non-empty strings")
        command = tuple(argv)
        if command not in self.policy.allowed_commands:
            raise AgentError("command is not explicitly allowed")
        return command

    def _run_command(self, argv: tuple[str, ...]) -> tuple[str, tuple[str, ...]]:
        """Execute one command with a hard timeout, returning bounded output."""

        process = subprocess.Popen(
            list(argv),
            cwd=self.policy.root,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            start_new_session=True,
        )
        timeout = self.policy.command_timeout_seconds
        deadline = monotonic() + timeout
        output: list[bytes] = []
        finished = Event()
        warnings: tuple[str, ...] = ()

        def reader() -> None:
            try:
                while True:
                    chunk = process.stdout.read(1 << 16)
                    if not chunk:
                        break
                    output.append(chunk)
                    if (
                        sum(len(part) for part in output)
                        > self.policy.max_tool_output_chars
                    ):
                        break
            finally:
                finished.set()

        thread = Thread(target=reader, daemon=True)
        thread.start()
        try:
            # Drain the pipe until the reader finishes or the timeout fires.
            while thread.is_alive() and monotonic() < deadline:
                thread.join(timeout=0.05)
            if thread.is_alive():
                self._kill_and_reap(process)
                warnings = ("command timed out and was killed",)
                thread.join(timeout=2.0)
            else:
                process.wait(timeout=2.0)
        finally:
            if thread.is_alive():
                thread.join(timeout=2.0)
        self.uncertain_modified_files.update(self._recent_modified())
        return self._truncate_result(
            b"".join(output).decode("utf-8", errors="replace"),
            preserve_command_warnings=warnings,
        )

    def _recent_modified(self) -> set[Path]:
        """Return files changed inside the workspace since the last snapshot."""

        changed: set[Path] = set()
        baseline = {path: digest for path, digest in self.observed_files.items()}
        for path in list(baseline):
            try:
                data = self._read_bounded_file(path, tool="run_command")
            except (OSError, ValueError, AgentError):
                changed.add(path)
                continue
            if self._digest(data) != baseline[path]:
                changed.add(path)
        return changed

    def _kill_and_reap(self, process) -> bool:
        """Terminate a whole process group and wait for it to exit."""

        try:
            os.killpg(process.pid, signal.SIGKILL)
        except (ProcessLookupError, PermissionError):
            try:
                process.kill()
            except ProcessLookupError:
                return process.poll() is not None
        try:
            process.wait(timeout=2.0)
        except subprocess.TimeoutExpired:
            return False
        return process.returncode is not None

    def _require_confirmation(self, action: ToolAction) -> None:
        """Default-deny one model-requested side effect."""

        if self.confirm_tool is None or not self.confirm_tool(action):
            raise AgentError(f"operator denied {action.tool}")

    def execute(self, action: ToolAction, *, tool_call_id: str | None = None) -> str:
        """Dispatch a validated action and return recoverable errors."""

        before_modified = frozenset(self.modified_files)
        before_uncertain = frozenset(self.uncertain_modified_files)
        try:
            if action.tool == "list_files":
                result = self.list_files(action.arguments.get("path", "."))
            elif action.tool == "read_file":
                result = self.read_file(action.arguments["path"])
            elif action.tool == "write_file":
                prepared = self._prepare_write(
                    action.arguments["path"], action.arguments["content"]
                )
                self._require_confirmation(action)
                result = self._commit_write(prepared)
            elif action.tool == "edit_file":
                prepared = self._prepare_edit(
                    action.arguments["path"],
                    action.arguments["old"],
                    action.arguments["new"],
                )
                self._require_confirmation(action)
                result = self._commit_write(prepared)
            elif action.tool == "run_command":
                command = self._prepare_command(action.arguments["argv"])
                self._require_confirmation(action)
                result = self._run_command(command)
            else:
                raise AgentError(f"unknown tool: {action.tool}")
        except (KeyError, OSError, subprocess.SubprocessError, ValueError) as error:
            result = f"error: {error}"
        truncated = self._truncate_result(result)
        self._record_receipt(
            action,
            truncated,
            tuple(
                sorted(
                    str(path.relative_to(self.policy.root))
                    for path in (self.modified_files | self.uncertain_modified_files)
                    - (before_modified | before_uncertain)
                )
            ),
            tool_call_id=tool_call_id,
        )
        return truncated

    def _truncate_result(
        self,
        result: str,
        *,
        preserve_command_warnings: tuple[str, ...] = (),
    ) -> str:
        """Bound a tool result to the configured output limit."""

        if len(result) <= self.policy.max_tool_output_chars:
            return result
        truncated = (
            result[: self.policy.max_tool_output_chars] + "\n[... truncated ...]"
        )
        if preserve_command_warnings:
            truncated += "\n" + "\n".join(preserve_command_warnings)
        return truncated

    def _open_parent_directory(self, relative: Path) -> tuple[int, str]:
        """Open the parent directory of a relative path without following links."""

        flags = (
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0)
        )
        directory = os.open(self.policy.root, flags)
        try:
            for part in relative.parts[:-1]:
                if part in {"", ".", ".."}:
                    raise AgentError("path is unsafe")
                if _protected_path_reason((part,)):
                    raise AgentError(_protected_path_reason((part,)))
                try:
                    directory = os.open(part, flags, dir_fd=directory)
                except OSError as error:
                    raise AgentError("path is unsafe") from error
            return directory, relative.name
        except BaseException:
            os.close(directory)
            raise

    def _read_regular_at(
        self, parent: int, name: str, *, tool: str
    ) -> tuple[bytes, os.stat_result] | None:
        """Read one bounded regular file by parent dir fd, rejecting links."""

        try:
            descriptor = os.open(
                name,
                os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0),
                dir_fd=parent,
            )
        except FileNotFoundError:
            return None
        except OSError as error:
            raise AgentError(f"{tool} path is unsafe") from error
        try:
            status = os.fstat(descriptor)
            if not stat.S_ISREG(status.st_mode) or status.st_nlink != 1:
                raise AgentError(f"{tool} path is not a regular file")
            if status.st_size > self.policy.max_file_bytes:
                raise AgentError(
                    f"{tool} file exceeds {self.policy.max_file_bytes} bytes"
                )
            data = b""
            while True:
                chunk = os.read(descriptor, 1 << 16)
                if not chunk:
                    break
                data += chunk
                if len(data) > self.policy.max_file_bytes:
                    raise AgentError(
                        f"{tool} file exceeds {self.policy.max_file_bytes} bytes"
                    )
            return data, status
        finally:
            os.close(descriptor)

    def _revalidate_prepared_write(self, prepared: _PreparedWrite) -> None:
        """Reject a write whose target changed after preparation."""

        path = prepared.path
        relative = path.relative_to(self.policy.root)
        parent, name = self._open_parent_directory(relative)
        try:
            current = self._read_regular_at(parent, name, tool="write_file")
        finally:
            os.close(parent)
        if current is None:
            if prepared.expected_digest is not None:
                raise AgentError("file changed since it was read; read it again")
            return
        current_content, current_status = current
        if prepared.expected_digest is None:
            raise AgentError("file changed since it was read; read it again")
        if self._digest(current_content) != prepared.expected_digest:
            raise AgentError("file changed since it was read; read it again")
        if stat.S_IMODE(current_status.st_mode) & 0o777 != prepared.expected_mode:
            raise AgentError("file mode changed since it was read; read it again")

    def _read_bounded_file(self, path: Path, *, tool: str) -> bytes:
        """Read one bounded regular file, rejecting symlinks and special files."""

        try:
            descriptor = os.open(
                path,
                os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0),
            )
        except OSError as error:
            raise AgentError(f"{tool} path is unsafe or missing") from error
        try:
            status = os.fstat(descriptor)
            if not stat.S_ISREG(status.st_mode) or status.st_nlink != 1:
                raise AgentError(f"{tool} path is not a regular file")
            if status.st_size > self.policy.max_file_bytes:
                raise AgentError(
                    f"{tool} file exceeds {self.policy.max_file_bytes} bytes"
                )
            data = b""
            while True:
                chunk = os.read(descriptor, 1 << 16)
                if not chunk:
                    break
                data += chunk
                if len(data) > self.policy.max_file_bytes:
                    raise AgentError(
                        f"{tool} file exceeds {self.policy.max_file_bytes} bytes"
                    )
            return data
        finally:
            os.close(descriptor)

    @staticmethod
    def _digest(content: bytes) -> bytes:
        """Fingerprint observed bytes for stale-write detection."""

        return hashlib.sha256(content).digest()

    def _atomic_write(
        self,
        path: Path,
        content: bytes,
        *,
        expected_digest: bytes | None,
        expected_mode: int | None,
        after_mode: int,
        parent_identity: tuple[int, int],
    ) -> None:
        """Atomically replace a file inside the workspace, fsyncing parents."""

        relative = path.relative_to(self.policy.root)
        parent, name = self._open_parent_directory(relative)
        temporary = None
        try:
            status = os.fstat(parent)
            if (status.st_dev, status.st_ino) != parent_identity:
                raise AgentError("parent directory changed during the write")
            if expected_digest is not None:
                current = self._read_regular_at(parent, name, tool="write_file")
                if current is None:
                    raise AgentError("file changed since it was read; read it again")
                current_content, current_status = current
                if self._digest(current_content) != expected_digest:
                    raise AgentError("file changed since it was read; read it again")
                if stat.S_IMODE(current_status.st_mode) & 0o777 != expected_mode:
                    raise AgentError(
                        "file mode changed since it was read; read it again"
                    )
            temporary = f".{name}.{uuid.uuid4().hex}.tmp"
            descriptor = os.open(
                temporary,
                os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0),
                0o600,
                dir_fd=parent,
            )
            try:
                view = memoryview(content)
                while view:
                    written = os.write(descriptor, view)
                    view = view[written:]
                os.fchmod(descriptor, after_mode)
                os.fsync(descriptor)
            finally:
                os.close(descriptor)
            os.rename(temporary, name, src_dir_fd=parent, dst_dir_fd=parent)
            os.fsync(parent)
        finally:
            if temporary is not None:
                try:
                    os.unlink(temporary, dir_fd=parent)
                except FileNotFoundError:
                    pass
            os.close(parent)
